print(edge_count([[1], [2], [0]], True))
print(edge_count([], False))

def empty_graph(n):
    adjacency = []
    for vertex in range(n):
        adjacency.append([])
    return adjacency

def valid_vertex(adjacency, vertex):
    return 0 <= vertex < len(adjacency)

def has_edge(adjacency, source, target):
    if not valid_vertex(adjacency, source) or not valid_vertex(adjacency, target):
        return False
    for neighbor in adjacency[source]:
        if neighbor == target:
            return True
    return False

def add_edge(adjacency, source, target, directed):
    if not valid_vertex(adjacency, source) or not valid_vertex(adjacency, target):
        return False
    if source == target or has_edge(adjacency, source, target):
        return False
    adjacency[source].append(target)
    if not directed:
        adjacency[target].append(source)
    return True

def build_graph(n, edges, directed):
    if n < 0:
        return None
    adjacency = empty_graph(n)
    for edge in edges:
        source = edge[0]
        target = edge[1]
        if not valid_vertex(adjacency, source) or not valid_vertex(adjacency, target):
            return None
        if source == target:
            return None
        add_edge(adjacency, source, target, directed)
    return adjacency

def remove_neighbor(neighbors, target):
    for i in range(len(neighbors)):
        if neighbors[i] == target:
            neighbors.pop(i)
            return True
    return False

def remove_edge(adjacency, source, target, directed):
    if not valid_vertex(adjacency, source) or not valid_vertex(adjacency, target):
        return False
    if source == target:
        return False
    removed = remove_neighbor(adjacency[source], target)
    if removed and not directed:
        remove_neighbor(adjacency[target], source)
    return removed

