def is_walk(adjacency, route):
    if len(route) == 0:
        return False
    for vertex in route:
        if not valid_vertex(adjacency, vertex):
            return False
    for i in range(1, len(route)):
        if not has_edge(adjacency, route[i - 1], route[i]):
            return False
    return True

